class MarginExchangePanel extends ConsumerStatefulWidget{const MarginExchangePanel({super.key,required this.workspace});final MarginWorkspace workspace;@override ConsumerState<MarginExchangePanel> createState()=>_MarginExchangePanelState();}
class _MarginExchangePanelState extends ConsumerState<MarginExchangePanel>{String? _recipient;String _kind='sync';
 Future<void> _export()async{final w=widget.workspace;if(!await marginConfirm(context,'Prepare recipient-encrypted package?',_kind=='policy'?'Includes owner-signed access policy and selected device roster, but no annotation content. Deliver it explicitly; offline devices do not learn permission changes automatically.':'Includes ALL selected workspace entries and retained revision history, including deleted versions, and the selected device roster. No private library originals are included. Preparing a package is not delivery.')){return;}if(!mounted){return;}String? packet;final ok=await marginChange(context,ref,(r){packet=r.margins('export',{'workspace_id':w.id,'recipient':_recipient,'kind':_kind}) as String;});if(ok&&mounted){await marginCode(context,'Encrypted $_kind package',packet!);}}
 @override Widget build(BuildContext context){final w=widget.workspace;return ListView(padding:const EdgeInsets.all(16),children:[
 SwitchListTile(title:const Text('Enable manual foreground exchange'),subtitle:const Text('No automatic network or background task. Pausing does not retract previously received copies.'),value:w.enabled,onChanged:w.role=='removed'?null:(v)async{if(v&&!await marginConfirm(context,'Enable manual exchange?','Only explicit export/import actions exchange data. Local changes stay saved while paused.')){return;}if(!context.mounted){return;}await marginChange(context,ref,(r)=>r.margins('enable',{'id':w.id,'enabled':v}));}),
 Text('Local persistence revision ${w.localRevision} · ${w.pendingTransfers} unacknowledged prepared transfer(s). These are not a percentage or a “fully synced” claim.'),
 OutlinedButton(onPressed:()=>context.push('/margins/import'),child:const Text('Inspect / import encrypted package')),
 if(w.canEdit)...[DropdownButtonFormField<String>(initialValue:_kind,decoration:const InputDecoration(labelText:'Transfer kind'),items:[const DropdownMenuItem(value:'sync',child:Text('Shared state update')),if(w.role=='owner')...const[DropdownMenuItem(value:'invite',child:Text('Invitation with shared history')),DropdownMenuItem(value:'policy',child:Text('Access policy only (including removal)'))]],onChanged:(v)=>setState((){_kind=v!;_recipient=null;})),
 ref.watch(marginPeersProvider(w.id)).when(loading:marginLoading,error:(e,_)=>marginError(e),data:(all){final peers=all.where((p)=>p.contact.key!=w.myKey&&(_kind=='policy'||p.role!='removed')).toList();return Column(children:[DropdownButtonFormField<String>(key:ValueKey('$_kind:$_recipient'),initialValue:peers.any((p)=>p.contact.key==_recipient)?_recipient:null,isExpanded:true,decoration:const InputDecoration(labelText:'Selected recipient device'),items:peers.map((p)=>DropdownMenuItem(value:p.contact.key,child:Text('${p.contact.name} · ${p.role}',overflow:TextOverflow.ellipsis))).toList(),onChanged:(v)=>setState(()=>_recipient=v)),FilledButton(onPressed:w.enabled&&peers.any((p)=>p.contact.key==_recipient)?_export:null,child:const Text('Review & prepare encrypted transfer'))]);})],
 const ListTile(title:Text('Latest 100 transfer records'),subtitle:Text('Receipt = selected peer signed a claim of import. It is not proof of reading, honest remote storage or universal convergence.')),
 ref.watch(marginTransfersProvider(w.id)).when(loading:marginLoading,error:(e,_)=>marginError(e),data:(rows)=>Column(children:rows.map((t)=>ExpansionTile(title:Text('${t['direction']} · ${t['kind']} · ${t['acknowledged_ts']==null?'delivery unconfirmed':'peer receipt recorded'}'),subtitle:Text(marginTime(t['created_ts'])),children:[SelectableText('Packet ${t['hash']}\nPeer ${t['peer_key']}'),if(t['direction']=='out'&&w.canEdit)TextButton(onPressed:!w.enabled?null:()async{String? packet;final ok=await marginChange(context,ref,(r){packet=r.margins('retry',{'id':w.id,'hash':t['hash']}) as String;});if(ok&&context.mounted){await marginCode(context,'Retry identical encrypted package',packet!);}},child:const Text('Show identical outgoing package')),if(t['direction']=='in'&&t['kind']!='receipt')TextButton(onPressed:!w.enabled||w.role=='removed'?null:()async{String? packet;final ok=await marginChange(context,ref,(r){packet=r.margins('receipt',{'id':w.id,'hash':t['hash']}) as String;});if(ok&&context.mounted){await marginCode(context,'Encrypted signed import receipt',packet!);}},child:const Text('Prepare signed import receipt'))])).toList())),
 ]);}
}
class MarginImportPage extends ConsumerStatefulWidget{const MarginImportPage({super.key});@override ConsumerState<MarginImportPage> createState()=>_MarginImportPageState();}
class _MarginImportPageState extends ConsumerState<MarginImportPage>{final _packet=TextEditingController(),_owner=TextEditingController();Map<String,dynamic>? _preview;bool _verified=false,_busy=false;String? _imported;
 @override void dispose(){_packet.dispose();_owner.dispose();super.dispose();}
 Future<void> _pickFile()async{try{final chosen=await FilePicker.platform.pickFiles(type:FileType.custom,allowedExtensions:['json'],withData:false,withReadStream:true);if(chosen==null){return;}final file=chosen.files.single;if(file.size>1600000){throw StateError('Package exceeds 1.6 MB limit');}final stream=file.readStream??(file.path==null?throw StateError('No readable file'):File(file.path!).openRead());final bytes=BytesBuilder(copy:false);await for(final chunk in stream){if(bytes.length+chunk.length>1600000){throw StateError('Package exceeds size limit');}bytes.add(chunk);}final text=utf8.decode(bytes.takeBytes());if(mounted){setState((){_packet.text=text;_preview=null;_verified=false;_imported=null;});}}catch(e){if(mounted){ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('$e')));}}}
 Future<void> _inspect()async{setState(()=>_busy=true);Map<String,dynamic>? result;final ok=await marginChange(context,ref,(r){result=r.margins('inspect',_packet.text) as Map<String,dynamic>;});if(mounted){setState((){_busy=false;_preview=ok?result:null;_verified=false;_owner.clear();});}}
 Future<void> _import()async{final preview=_preview;if(preview==null||!_verified||_owner.text.trim()!=preview['owner']){ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Independently verify and enter the full owner fingerprint.')));return;}setState(()=>_busy=true);Map<String,dynamic>? result;final ok=await marginChange(context,ref,(r){result=r.margins('import',{'packet':_packet.text,'expected_owner':_owner.text.trim()}) as Map<String,dynamic>;});if(mounted){setState(()=>_busy=false);if(ok){setState(()=>_imported=result!['workspace_id'] as String);ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(result!['explanation'] as String)));}}}
 @override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Review encrypted exchange')),body:ListView(padding:const EdgeInsets.all(16),children:[
 const Text('Nothing is merged until you inspect and explicitly accept. Private keys never leave this device. New invitations require independent owner-fingerprint verification. Further exchange on a newly joined workspace starts paused.'),
 OutlinedButton.icon(onPressed:_busy?null:_pickFile,icon:const Icon(Icons.file_open_outlined),label:const Text('Open encrypted package file')),TextField(controller:_packet,maxLines:5,maxLength:1600000,decoration:const InputDecoration(labelText:'Recipient-encrypted package JSON'),onChanged:(_)=>setState((){_preview=null;_verified=false;_imported=null;})),FilledButton(onPressed:_busy||_packet.text.isEmpty?null:_inspect,child:const Text('Decrypt & inspect without merging')),
 if(_preview!=null)...[Text('${_preview!['name']} · ${_preview!['kind']} · epoch ${_preview!['epoch']}'),Text('Proposed access: ${_preview!['my_role']} · ${_preview!['revision_count']} retained revisions'),SelectableText('Owner fingerprint:\n${_preview!['owner']}\nVerified exporter key:\n${_preview!['sender']}'),Text(_preview!['warning'] as String),ExpansionTile(title:const Text('Shared content & selected devices in this package'),children:[...marginRows(_preview!,'members').map((m)=>ListTile(title:Text('${(m['contact'] as Map)['data']['name']} · ${m['role']}'))),...marginRows(_preview!,'entries').map((e)=>ListTile(title:Text('${e['title']} · ${e['deleted']==true?'deleted version':'retained'}'),subtitle:Text(e['body'] as String)))]),TextField(controller:_owner,maxLength:64,decoration:const InputDecoration(labelText:'Full owner fingerprint independently confirmed'),onChanged:(_)=>setState((){})),CheckboxListTile(value:_verified,onChanged:(v)=>setState(()=>_verified=v??false),title:const Text('I verified the full owner fingerprint using a trusted channel')),FilledButton(onPressed:_busy||!_verified||_owner.text.trim()!=_preview!['owner']?null:_import,child:const Text('Accept & merge this reviewed package'))],
 if(_imported!=null)TextButton(onPressed:()=>context.push('/margins/workspace/$_imported'),child:const Text('Open imported workspace')),
 ]));
}
class MarginMemberPage extends ConsumerStatefulWidget{const MarginMemberPage({super.key,required this.id});final String id;@override ConsumerState<MarginMemberPage> createState()=>_MarginMemberPageState();}
class _MarginMemberPageState extends ConsumerState<MarginMemberPage>{final _card=TextEditingController();MarginContact? _contact;String _role='viewer';bool _verified=false;
 @override void dispose(){_card.dispose();super.dispose();}
 Future<void> _inspect()async{MarginContact? contact;final ok=await marginChange(context,ref,(r){final parsed=jsonDecode(_card.text) as Map<String,dynamic>;contact=MarginContact.fromJson(r.margins('verify_contact',parsed) as Map<String,dynamic>);});if(mounted){setState((){_contact=ok?contact:null;_verified=false;});}}
 @override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Selected device permissions')),body:ListView(padding:const EdgeInsets.all(16),children:[
 const Text('Owner-only. A valid self-signed contact card binds device keys, not a real-world identity. Verify its full fingerprint through a trusted channel. Changing access does not automatically contact peers or erase old copies.'),
 TextField(controller:_card,maxLines:5,maxLength:12000,decoration:const InputDecoration(labelText:'Public contact card JSON'),onChanged:(_)=>setState((){_contact=null;_verified=false;})),TextButton(onPressed:_inspect,child:const Text('Validate public contact card')),
 if(_contact!=null)...[Text(_contact!.name),SelectableText(_contact!.key),DropdownButtonFormField<String>(initialValue:_role,decoration:const InputDecoration(labelText:'Access'),items:const[DropdownMenuItem(value:'viewer',child:Text('Read-only')),DropdownMenuItem(value:'editor',child:Text('Collaborative editing (all shared content)')),DropdownMenuItem(value:'removed',child:Text('Remove from future exchange'))],onChanged:(v)=>setState(()=>_role=v!)),CheckboxListTile(value:_verified,onChanged:(v)=>setState(()=>_verified=v??false),title:const Text('I independently verified this full device fingerprint')),FilledButton(onPressed:!_verified?null:()async{if(!await marginConfirm(context,'Update selected-device access?','The owner-signed policy epoch will advance. Send policy updates explicitly; offline peers keep using their last known policy until they receive one.')){return;}if(!context.mounted){return;}final ok=await marginChange(context,ref,(r)=>r.margins('member',{'id':widget.id,'contact':_contact!.toJson(),'role':_role}));if(ok&&context.mounted){context.pop();}},child:const Text('Save owner-signed permissions'))],
 ]));
}
